import { createServer } from 'node:http';
import { once } from 'node:events';

/** A small Jellyfin-shaped library; all media is generated by the test. */
export async function fakeJellyfin(filename: string, duration = 90) {
  const summary = (Id: string, Name: string, Type: string, IsFolder: boolean) => ({ Id, Name, Type, IsFolder, MediaType: IsFolder ? undefined : 'Video' });
  const movie = summary('b2', 'Signal / Noise', 'Movie', false);
  const episode = { ...summary('c3', 'A new frequency', 'Episode', false), SeriesName: 'After Hours', ParentIndexNumber: 1, IndexNumber: 1 };
  const requests: URL[] = [];
  const server = createServer((req, res) => {
    const url = new URL(req.url ?? '/', 'http://localhost'); requests.push(url);
    if (!req.headers.authorization?.startsWith('MediaBrowser ') || !req.headers.authorization.includes('Token="fixture-key"')) { res.writeHead(401); res.end(); return; }
    const parent = url.searchParams.get('ParentId'); let Items: unknown[] = [];
    if (url.pathname === '/Users/abc123/Views') Items = [summary('a1', 'Movies', 'CollectionFolder', true), summary('a2', 'TV Shows', 'CollectionFolder', true)];
    else if (url.pathname === '/Users/abc123/Items') {
      if (url.searchParams.has('SearchTerm')) Items = [movie, episode];
      else if (parent === 'a1') Items = [movie];
      else if (parent === 'a2') Items = [summary('c1', 'After Hours', 'Series', true)];
      else if (parent === 'c1') Items = [summary('c2', 'Season 1', 'Season', true)];
      else if (parent === 'c2') Items = [episode];
    } else if (/^\/Users\/abc123\/Items\/(b2|c3)$/.test(url.pathname)) {
      res.setHeader('Content-Type', 'application/json'); res.end(JSON.stringify({ ...(url.pathname.endsWith('/c3') ? episode : movie), Path: filename, RunTimeTicks: duration * 10_000_000,
        MediaStreams: [{ Index: 0, Type: 'Video', Codec: 'h264' }, { Index: 1, Type: 'Audio', DisplayTitle: 'English', Codec: 'aac' }] })); return;
    } else { res.writeHead(404); res.end(); return; }
    const start = Number(url.searchParams.get('StartIndex') ?? '0');
    res.setHeader('Content-Type', 'application/json'); res.end(JSON.stringify({ Items: Items.slice(start, start + 100), TotalRecordCount: Items.length }));
  });
  server.listen(0, '127.0.0.1'); await once(server, 'listening');
  const address = server.address(); if (!address || typeof address === 'string') throw new Error('No fixture listener');
  return { url: `http://127.0.0.1:${address.port}`, requests, close: () => new Promise<void>(resolve => { server.closeAllConnections(); server.close(() => resolve()); }) };
}
